arguments.command:
cd /app; cat > /tmp/t.js <<'EOF'
const c=require("crypto"),fs=require("fs");
const recs=require("/app/requests/sample-requests.json");
const bc=(a,b)=>Buffer.compare(Buffer.from(a),Buffer.from(b));
function canon(r,o){
 const t=r.target,q=t.indexOf("?"),path=q<0?t:t.slice(0,q),query=q<0?"":t.slice(q+1);
 let p=query===""?[]:query.split("&").map(s=>{const e=s.indexOf("=");return e<0?[s,""]:[s.slice(0,e),s.slice(e+1)]});
 p=p.map((x,i)=>[...x,i]).sort((a,b)=>bc(a[0],b[0])||(o.qv?bc(a[1],b[1]):0)||a[2]-b[2]);
 const cq=p.map(([n,v])=>`${n}=${v}`).join("&");
 let h=r.headers.map(([n,v],i)=>[n.toLowerCase(),v,i]).filter(([n])=>o.hs==="all"?n!=="authorization":o.hs==="gwct"?(n.startsWith("x-gw-")||n==="content-type"):n.startsWith("x-gw-"));
 h.sort((a,b)=>bc(a[0],b[0])||a[2]-b[2]);
 const hv=v=>o.hv==="collapse"?v.replace(/^[ \t]+|[ \t]+$/g,"").replace(/[ \t]+/g," "):o.hv==="trim"?v.replace(/^[ \t]+|[ \t]+$/g,""):v;
 const body=r.body;
 const bh=o.bh==="sha"?c.createHash("sha256").update(body??"").digest("hex"):(body??"")===""?"UNSIGNED":c.createHash("sha256").update(body).digest("hex");
 return [r.method.toUpperCase(),path,cq,h.map(([n,v])=>`${n}:${hv(v)}`).join("\n"),h.map(x=>x[0]).join(o.sep),bh].join("\n")+(o.lf?"\n":"");
}
for(const i of [5,6]){const r=recs[i];const kid=r.headers.find(h=>h[0].toLowerCase()=="x-gw-key-id")[1];
 const want=r.headers.find(h=>h[0]=="Authorization")[1].split("signature=")[1];
 const raw=fs.readFileSync(`/app/keys/${kid}.key`);
 for(const kw of [0,1])for(const qv of [0,1])for(const hs of ["all","gwct","gw"])for(const hv of ["collapse","trim","none"])for(const bh of ["sha","uns"])for(const sep of [";",","])for(const lf of [0,1]){
  const o={qv,hs,hv,bh,sep,lf};const key=kw?raw:raw.subarray(0,raw.length-1);
  if(c.createHmac("sha256",key).update(canon(r,o)).digest("hex")===want)console.log(i+1,"keyWhole="+kw,JSON.stringify(o));}}
EOF
node /tmp/t.js

